import type { MetadataRoute } from "next";

/**
 * PWA manifest (PRD §31, v0.2; install polish v0.7): installable, standalone,
 * white background to match the default theme. Icons are generated by
 * scripts/build-icons.mjs, screenshots by scripts/capture-screenshots.mjs.
 *
 * `id` pins the app identity so a redeploy can never register as a second
 * install, and `launch_handler` reuses the window that is already open
 * instead of stacking duplicates.
 *
 * The manifest is a fixed object, so it is declared static — that is what lets
 * the Android build (`output: "export"`) include it. An unmarked route counts
 * as dynamic and blocks the export.
 */
export const dynamic = "force-static";

export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "NBA 比分",
    short_name: "NBA比分",
    description: "今天的 NBA 比分。打开、扫一眼、关掉。",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    // The manifest is static (see `dynamic` above), so it cannot follow the
    // in-app theme. The browser chrome uses the viewport meta instead, which
    // does carry both schemes; these two values stay the white install surface.
    background_color: "#ffffff",
    theme_color: "#ffffff",
    lang: "zh-CN",
    dir: "ltr",
    categories: ["sports", "news"],
    prefer_related_applications: false,
    launch_handler: { client_mode: "focus-existing" },
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png" },
      {
        src: "/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
    screenshots: [
      {
        src: "/screenshots/home.png",
        sizes: "780x1688",
        type: "image/png",
        form_factor: "narrow",
        label: "今日赛程，比分一眼看完",
      },
      {
        src: "/screenshots/detail.png",
        sizes: "780x1688",
        type: "image/png",
        form_factor: "narrow",
        label: "比赛详情、动态与投篮分布",
      },
    ],
  };
}
